insert into public.proyectos (slug, nombre, titulo, categoria, lugar, anio, m2, texto, publicado, orden, galeria, mostrar, fotos, portada) values
('exposicion-a-cidade-e-a-pegada','Exposición A cidade é a pegada','Exposición A cidade é a pegada','Otros','Pontevedra',null,null,array['NAN Arquitectos participa en A cidade é a pegada, una exposición organizada por el Ayuntamiento de Pontevedra que explora cómo la ciudad deja huella en quienes la habitan con salas dedicadas al río, a sus personajes históricos, la infancia y la arquitectura.','El estudio desarrolla el contenido y el diseño de la sala dedicada a la arquitectura y el urbanismo,  creando maquetas de edificios representativos del desarrollismo pontevedrés, reuniendo planos históricos y fotografías de rincones de la ciudad, generando una mirada nueva a través de un panel de fotografías de la actualidad y un elemento indicativo de la evolución del urbanismo de la ciudad. Una mirada que invita a descubrir cómo los espacios construidos forman parte de nuestra memoria y experiencia cotidiana.','Comisario da exposición: Alfredo Olmedo Portela','Co-comisario sala río: Eduardo Outeiro Ferreño','Co-comisaria sala personaxes: Milagros Bará Viñas','Co-comisario sala infancia: Norberto Olmedo Portela']::text[],true,0,'mosaico','{"ficha": true, "texto": true, "galeria": true, "planos": true, "siguiente": true}'::jsonb,'[{"id": "exposicion-a-cidade-e-a-pegada-0", "repo": "exposicion-a-cidade-e-a-pegada/01.jpg"}, {"id": "exposicion-a-cidade-e-a-pegada-1", "repo": "exposicion-a-cidade-e-a-pegada/02.jpg"}, {"id": "exposicion-a-cidade-e-a-pegada-2", "repo": "exposicion-a-cidade-e-a-pegada/03.jpg"}, {"id": "exposicion-a-cidade-e-a-pegada-3", "repo": "exposicion-a-cidade-e-a-pegada/04.jpg"}, {"id": "exposicion-a-cidade-e-a-pegada-4", "repo": "exposicion-a-cidade-e-a-pegada/05.jpg"}, {"id": "exposicion-a-cidade-e-a-pegada-5", "repo": "exposicion-a-cidade-e-a-pegada/06.jpg"}, {"id": "exposicion-a-cidade-e-a-pegada-6", "repo": "exposicion-a-cidade-e-a-pegada/07.jpg"}]'::jsonb,null),
('vivienda-forcarei','Vivienda Forcarei','Vivienda Forcarei','Vivienda','Pontevedra',null,null,'{}'::text[],true,1,'mosaico','{"ficha": true, "texto": true, "galeria": true, "planos": true, "siguiente": true}'::jsonb,'[{"id": "vivienda-forcarei-0", "repo": "vivienda-forcarei/01.jpg"}, {"id": "vivienda-forcarei-1", "repo": "vivienda-forcarei/02.jpg"}, {"id": "vivienda-forcarei-2", "repo": "vivienda-forcarei/03.jpg"}, {"id": "vivienda-forcarei-3", "repo": "vivienda-forcarei/04.jpg"}]'::jsonb,null),
('centro-de-salud-deportiva-y-podologia','centro de salud deportiva y podología','Centro de salud deportiva y podología Pedro Lago','Clínica','Vilagarcía de Arousa',2025,250.0,array['Este centro de salud deportiva y podología, concebido con la pureza estética de NAN, combina innovación, funcionalidad y una identidad visual única.','El proyecto se estructura en volúmenes independientes que albergan las áreas de tratamiento y un quirófano con tecnología de vanguardia. En su base, el vidrio actúa como guiño sutil al pie, eje conceptual de la propuesta.','La identidad deportiva se refleja en el pavimento amortiguado de PVC, que integra una pista de atletismo para transmitir dinamismo y energía. La paleta cromática, dominada por grises y matices cálidos, refuerza la imagen corporativa y aporta serenidad.','La iluminación, protagonista en el recorrido, guía al visitante con líneas continuas y luz difusa en las zonas de trabajo, evitando sombras. La señalética retroiluminada facilita la orientación y aporta un toque distintivo al conjunto.','Un espacio que no solo cuida del cuerpo, sino que envuelve al visitante en una experiencia arquitectónica coherente, contemporánea y estimulante.']::text[],true,2,'mosaico','{"ficha": true, "texto": true, "galeria": true, "planos": true, "siguiente": true}'::jsonb,'[{"id": "centro-de-salud-deportiva-y-podologia-0", "repo": "centro-de-salud-deportiva-y-podologia/01.jpg"}, {"id": "centro-de-salud-deportiva-y-podologia-1", "repo": "centro-de-salud-deportiva-y-podologia/02.jpg"}, {"id": "centro-de-salud-deportiva-y-podologia-2", "repo": "centro-de-salud-deportiva-y-podologia/03.jpg"}, {"id": "centro-de-salud-deportiva-y-podologia-3", "repo": "centro-de-salud-deportiva-y-podologia/04.jpg"}, {"id": "centro-de-salud-deportiva-y-podologia-4", "repo": "centro-de-salud-deportiva-y-podologia/05.jpg"}, {"id": "centro-de-salud-deportiva-y-podologia-5", "repo": "centro-de-salud-deportiva-y-podologia/06.jpg"}, {"id": "centro-de-salud-deportiva-y-podologia-6", "repo": "centro-de-salud-deportiva-y-podologia/07.jpg"}]'::jsonb,null),
('marna-restaurante','Marna Restaurante','Restaurante MARNA','Hostelería','Pontevedra',2025,200.0,array['El restaurante Marna se inspira en la estética y valores de la tradición franciscana. El color marrón, símbolo del hábito de los hermanos menores, domina el espacio en maderas y revestimientos, creando un ambiente cálido y sobrio.','La barra, revestida en microcemento beige, se eleva como un altar contemporáneo, actuando como el centro simbólico y funcional del lugar. Celosías de madera, inspiradas en los confesionarios, dividen y conectan sutilmente los espacios, aportando intimidad y evocación espiritual.','La iluminación cálida, el uso de materiales nobles y una atmósfera contenida hacen de Marna un espacio de contemplación y encuentro, donde la experiencia gastronómica se convierte en un ritual moderno.']::text[],true,3,'sueltas','{"ficha": true, "texto": true, "galeria": true, "planos": true, "siguiente": true}'::jsonb,'[{"id": "marna-restaurante-0", "repo": "marna-restaurante/01.jpg"}, {"id": "marna-restaurante-1", "repo": "marna-restaurante/02.jpg"}, {"id": "marna-restaurante-2", "repo": "marna-restaurante/03.jpg"}, {"id": "marna-restaurante-3", "repo": "marna-restaurante/04.jpg"}, {"id": "marna-restaurante-4", "repo": "marna-restaurante/05.jpg"}, {"id": "marna-restaurante-5", "repo": "marna-restaurante/06.jpg"}, {"id": "marna-restaurante-6", "repo": "marna-restaurante/07.jpg"}]'::jsonb,null),
('clinica-mercedes-fayos-fons','Clínica Mercedes Fayos Fons','Clínica de ortodoncia Mercedes Fayos Fons','Clínica','Pontevedra',2024,200.0,array['Este proyecto de interiorismo parte de un concepto claro: diseñar una clínica especializada en ortodoncia que transmita transparencia, fluidez y cercanía, tanto hacia sus pacientes como hacia el entorno urbano en el que se inserta. La clínica se plantea como un espacio abierto al exterior, que elimina las barreras visuales y físicas para generar confianza y bienestar desde el primer contacto.','Fluidez espacial a través de volúmenes y membranas','El diseño interior se articula mediante un juego de volúmenes puros y membranas translúcidas que definen los distintos usos sin aislarlos completamente. Estas divisiones permiten que la luz natural fluya por todo el espacio, generando una atmósfera ligera y continua, donde es posible intuir el funcionamiento interno de la clínica sin comprometer la privacidad de los usuarios. Esta estrategia espacial potencia la legibilidad del programa funcional y mejora la orientación de los pacientes.','La elección de los materiales responde a un equilibrio entre la percepción de limpieza y tecnología, fundamental en un espacio sanitario, y la necesidad de crear un ambiente acogedor y cercano.','El aluminio, utilizado en revestimientos y detalles constructivos, aporta una imagen de alta tecnología, precisión y asepsia. Su acabado metálico y frío refuerza la idea de limpieza rigurosa y profesionalidad.','En contraposición, la madera natural de roble se introduce en mobiliario y revestimientos parciales para aportar calidez y confort sensorial, generando un ambiente que humaniza el tratamiento médico y disminuye la ansiedad del paciente.']::text[],true,4,'mosaico','{"ficha": true, "texto": true, "galeria": true, "planos": true, "siguiente": true}'::jsonb,'[{"id": "clinica-mercedes-fayos-fons-0", "repo": "clinica-mercedes-fayos-fons/01.jpg"}, {"id": "clinica-mercedes-fayos-fons-1", "repo": "clinica-mercedes-fayos-fons/02.jpg"}, {"id": "clinica-mercedes-fayos-fons-2", "repo": "clinica-mercedes-fayos-fons/03.jpg"}, {"id": "clinica-mercedes-fayos-fons-3", "repo": "clinica-mercedes-fayos-fons/04.jpg"}, {"id": "clinica-mercedes-fayos-fons-4", "repo": "clinica-mercedes-fayos-fons/05.jpg"}, {"id": "clinica-mercedes-fayos-fons-5", "repo": "clinica-mercedes-fayos-fons/06.jpg"}, {"id": "clinica-mercedes-fayos-fons-6", "repo": "clinica-mercedes-fayos-fons/07.jpg"}]'::jsonb,null),
('carlos-pons','Carlos Pons','Centro de belleza Carlos Pons','Comercio','Pontevedra',2025,220.0,array['En nuestro diseño, hemos incorporado elementos que buscan crear un espacio funcional, flexible y visualmente inspirador. A continuación, describimos los principales componentes y materiales que conforman este proyecto:','Las rocas: Estos elementos diferenciadores actúan como expositores y mostradores de cobro, tanto en la tienda como en el salón de belleza. Han sido construidos con materiales resistentes y de carácter, como el acero, que aporta durabilidad y un toque moderno. Su presencia no solo cumple una función práctica, sino que también aporta carácter y personalidad al espacio, sirviendo como puntos focales que atraen la atención y facilitan la interacción con los clientes.','Los puestos: Se han diseñado bloques simples que organizan de manera eficiente los diferentes usos y funcionalidades de los espacios. Estos puestos están construidos con materiales que combinan funcionalidad y estética, como el acero y la madera de roble, creando un contraste interesante y armonioso. Su sencillez permite una distribución clara y ordenada, facilitando la circulación y el acceso a los servicios ofrecidos.','Las cortinas: Inspiradas conceptualmente en el movimiento y la voluminosidad del cabello, estas cortinas fluyen suavemente, organizando los recorridos dentro del espacio. Además, ofrecen una flexibilidad notable, permitiendo configurar los ambientes según las necesidades de cada momento, creando espacios dinámicos y adaptables.','Las paredes: Han sido construidas con mortero, un material que aporta textura y un acabado sobrio, complementando los otros elementos y materiales del espacio. La elección del mortero ayuda a crear un ambiente cálido y acogedor, además de facilitar la integración con los otros componentes de acero y madera. Este enfoque busca fusionar funcionalidad con una estética inspirada en la belleza y el movimiento, logrando un ambiente acogedor, versátil y lleno de carácter, donde los materiales refuerzan la identidad del espacio.','La luz: Se integra en el perímetro del local una línea de luz empotrada en el pavimento, que aporta una luz ambiental cálida y envolvente. Esta iluminación baja contribuye a definir los recorridos y acentuar el carácter del espacio de forma sutil. El ambiente se refuerza mediante apliques verticales distribuidos en los paramentos, que aportan ritmo visual y acompañan el recorrido del usuario. Además, los puestos de trabajo de peluquería y maquillaje se iluminan de forma cenital y frontal, asegurando una luz funcional, nítida y precisa, indispensable para las tareas que se realizan. Esta combinación de capas lumínicas permite generar una atmósfera equilibrada, confortable y coherente con la identidad del proyecto.']::text[],true,5,'mosaico','{"ficha": true, "texto": true, "galeria": true, "planos": true, "siguiente": true}'::jsonb,'[{"id": "carlos-pons-0", "repo": "carlos-pons/01.jpg"}, {"id": "carlos-pons-1", "repo": "carlos-pons/02.jpg"}, {"id": "carlos-pons-2", "repo": "carlos-pons/03.jpg"}, {"id": "carlos-pons-3", "repo": "carlos-pons/04.jpg"}, {"id": "carlos-pons-4", "repo": "carlos-pons/05.jpg"}, {"id": "carlos-pons-5", "repo": "carlos-pons/06.jpg"}, {"id": "carlos-pons-6", "repo": "carlos-pons/07.jpg"}]'::jsonb,null),
('reforma-vivienda-en-o-grove','Reforma vivienda en O Grove','Rehabilitación de vivienda CC','Vivienda','O Grove',2024,150.0,'{}'::text[],true,6,'mosaico','{"ficha": true, "texto": true, "galeria": true, "planos": true, "siguiente": true}'::jsonb,'[{"id": "reforma-vivienda-en-o-grove-0", "repo": "reforma-vivienda-en-o-grove/01.jpg"}, {"id": "reforma-vivienda-en-o-grove-1", "repo": "reforma-vivienda-en-o-grove/02.jpg"}, {"id": "reforma-vivienda-en-o-grove-2", "repo": "reforma-vivienda-en-o-grove/03.jpg"}, {"id": "reforma-vivienda-en-o-grove-3", "repo": "reforma-vivienda-en-o-grove/04.jpg"}, {"id": "reforma-vivienda-en-o-grove-4", "repo": "reforma-vivienda-en-o-grove/05.jpg"}, {"id": "reforma-vivienda-en-o-grove-5", "repo": "reforma-vivienda-en-o-grove/06.jpg"}, {"id": "reforma-vivienda-en-o-grove-6", "repo": "reforma-vivienda-en-o-grove/07.jpg"}]'::jsonb,null),
('vivienda-parche','Vivienda parche','Vivienda Parche','Vivienda','Pontevedra',2024,150.0,array['Iniciamos este proyecto con un importante aspecto a tener en cuenta, ya que se buscaba tener un espacio diáfano con funciones singulares como la de tener un amplio estudio de trabajo versátil donde la propietaria pudiese realizar su actividad profesional. Entendimos que este aspecto era importante y tratamos de integrar este espacio dentro de un conjunto de vivienda con una imagen muy heterogénea pero muy marcada y con mucha personalidad.','La vivienda consta de 3 habitaciones, un salón/comedor/cocina, 3 baños y un estudio de trabajo.','La idea es que en cualquier estancia de la vivienda tengamos una estética común a todo el conjunto, utilizando la misma paleta de materiales en todos los habitáculos. Para esto, utilizamos el pavimento existente combinado con elementos nuevos y se incorpora un aire clásico a todo el conjunto tiñendo la madera en un color oscuro y aportando notas de color en el mobiliario con amarillo pastel, azul celeste, granate y verde inglés para las puertas de todas las estancias, siendo una gama muy utilizada en la obra de la propietaria y haciendo recordar grandes obras de Le Corbusier o Robert Mallet-Stevens.','La zona de estudio de trabajo se convierte en espacio protagonista dentro de todo el conjunto del proyecto. Formalmente esto se traduce en una gran librería que forma un bloque que se une con la cocina y unas mesas con ruedas que puedan configurarse de diferentes maneras con el fin de ser versátiles dando múltiples situaciones de trabajo tanto colaborativo como individual.','Entendimos que la pre existencia con la que nos encontramos era muy interesante a nivel arquitectónico, ya que era un edificio de los años 60, clásico y con una estructura metálica que raramente se encuentra. Por este motivo intentamos ser muy conservadores y respetuosos con el esquema y los materiales con los que nos encontramos y tratamos de introducir elementos que dialogasen de una manera fluida con lo existente.','La distribución del apartamento se hizo completamente nueva, por eso nos encontramos con el problema de los “vacíos” en donde se ubicaban los tabiques de la distribución anterior y superficies que tuvimos que readaptar para esconder instalaciones, algo que tratamos de convertir en virtud dentro del conjunto. Para este fin se ideó la colocación de un material que sirviese de hilo conductor a toda la intervención. Nos pareció apropiado la colocación de un cerámico 10×10 negro que contrastase de manera contundente con respecto a la madera y al terrazo rojo que nos encontramos en los pavimentos tan típico de la construcción de estos años. Se utiliza este material 10×10 a modo de “parche” lo que le da una lectura clara y sincera al conjunto de la intervención que se ha realizado. En los paramentos verticales jugamos con un zócalo del cerámico 10×10, con el fin de darle continuidad al suelo combinado con madera de la misma tonalidad que los pavimentos, donde ocultamos iluminación indirecta, cálida, con la idea de poder generar atmósferas más relajadas cuando se pretenda. Por lo tanto la iluminación también es un aspecto a destacar dentro del proyecto, marcando aquellos elementos arquitectónicos que consideramos más interesantes (panelados, estanterías,…) y generando diferentes ambientes dependiendo de la cantidad y tipo de luminaria que accionamos, el momento del día en el que vivamos y la actividad que se vaya a realizar.']::text[],true,7,'sueltas','{"ficha": true, "texto": true, "galeria": true, "planos": true, "siguiente": true}'::jsonb,'[{"id": "vivienda-parche-0", "repo": "vivienda-parche/01.jpg"}, {"id": "vivienda-parche-1", "repo": "vivienda-parche/02.jpg"}, {"id": "vivienda-parche-2", "repo": "vivienda-parche/03.jpg"}, {"id": "vivienda-parche-3", "repo": "vivienda-parche/04.jpg"}, {"id": "vivienda-parche-4", "repo": "vivienda-parche/05.jpg"}, {"id": "vivienda-parche-5", "repo": "vivienda-parche/06.jpg"}, {"id": "vivienda-parche-6", "repo": "vivienda-parche/07.jpg"}]'::jsonb,null),
('campana-bakery','Campaña bakery','Pastelería Campaña','Hostelería','Gutiérrez Mellado, Pontevedra',2024,20.0,array['Un espacio reducido destinado a punto de venta de pastelería y de café.','El cliente es una empresa ya establecida en otra ciudad donde sus productos son populares y con un elevado éxito de ventas.','La idea es la de poner en valor el producto que se va a distribuir. Que este producto sea el protagonista y que visualmente sea agradable para el cliente.','También consideramos importante que el espacio transmita tradición, por eso los materiales utilizados nos trasladan a estos valores, un ladrillo de barro macizo y un mostrador hecho de mortero de cal que se asocian a la arquitectura tradicional y al material utilizado en la producción de estos productos, como la harina.','Buscar que el local sea lo más homogéneo posible para evitar que la suma de materiales se confunda con el producto en venta. Para ello, el material principal es el que se extiende por el suelo y las paredes jugando con un mostrador/expositor que ocupa el espacio de escaparate y da servicio interior. La iluminación principal es una proyección del espacio de mostrador en forma de Z reforzado por la iluminación en las baldas de forma que toda la atención se centre en el producto.']::text[],true,8,'mosaico','{"ficha": true, "texto": true, "galeria": true, "planos": true, "siguiente": true}'::jsonb,'[{"id": "campana-bakery-0", "repo": "campana-bakery/01.jpg"}, {"id": "campana-bakery-1", "repo": "campana-bakery/02.jpg"}, {"id": "campana-bakery-2", "repo": "campana-bakery/03.jpg"}, {"id": "campana-bakery-3", "repo": "campana-bakery/04.jpg"}, {"id": "campana-bakery-4", "repo": "campana-bakery/05.jpg"}, {"id": "campana-bakery-5", "repo": "campana-bakery/06.jpg"}, {"id": "campana-bakery-6", "repo": "campana-bakery/07.jpg"}]'::jsonb,null),
('pumper-take-away','Pumper take away','Pumper take away','Hostelería','Pontevedra',2024,15.0,array['Proyecto de take away de panadería y cafetería en un espacio mínimo.','La imagen es una continuación estética del espacio ya diseñado anteriormente por nuestro estudio para estos promotores, la cafetería matriz.','La idea es continuar en este espacio tan reducido con unos valores de sostenibilidad de la filosofía Pumper, a través de los materiales y de un diseño minimalista.','El reto es conjugar en un habitáculo tan pequeño todas las funciones necesarias de venta y exposición con el aspecto limpio y minimalista que se busca como imagen.','Un conjunto que busca un aspecto muy homogéneo en todos sus elementos. La sostenibilidad y la tradición son los mensajes que queremos trasmitir, para ellos se trabaja con morteros y se combinan con madera para trasladarnos a la idea de la leña, elemento protagonista en cualquier panadería de antaño.','Se busca también una iluminación limpia y minimalista. Procuramos un espacio bien iluminado evitando la formación de sombras y buscando una luz nítida. Los elementos de iluminación son formas geométricas sin ningún tipo de ornamentación.']::text[],true,9,'mosaico','{"ficha": true, "texto": true, "galeria": true, "planos": true, "siguiente": true}'::jsonb,'[{"id": "pumper-take-away-0", "repo": "pumper-take-away/01.jpg"}, {"id": "pumper-take-away-1", "repo": "pumper-take-away/02.jpg"}, {"id": "pumper-take-away-2", "repo": "pumper-take-away/03.jpg"}, {"id": "pumper-take-away-3", "repo": "pumper-take-away/04.jpg"}, {"id": "pumper-take-away-4", "repo": "pumper-take-away/05.jpg"}, {"id": "pumper-take-away-5", "repo": "pumper-take-away/06.jpg"}, {"id": "pumper-take-away-6", "repo": "pumper-take-away/07.jpg"}]'::jsonb,null),
('vivienda-resille','vivienda resille','Vivienda en Resille','Vivienda','Bueu',2024,150.0,'{}'::text[],true,10,'mosaico','{"ficha": true, "texto": true, "galeria": true, "planos": true, "siguiente": true}'::jsonb,'[{"id": "vivienda-resille-0", "repo": "vivienda-resille/01.jpg"}, {"id": "vivienda-resille-1", "repo": "vivienda-resille/02.jpg"}, {"id": "vivienda-resille-2", "repo": "vivienda-resille/03.jpg"}, {"id": "vivienda-resille-3", "repo": "vivienda-resille/04.jpg"}, {"id": "vivienda-resille-4", "repo": "vivienda-resille/05.jpg"}, {"id": "vivienda-resille-5", "repo": "vivienda-resille/06.jpg"}]'::jsonb,null),
('ayuntamiento-pontevedra','ayuntamiento PONTEVEDRA','Reforma de dependencias municipales, ayuntamiento Pontevedra','Oficina','Calle Michelena 30, Pontevedra',2020,530.0,array['Debido a la pandemia instalada en nuestro país a principios de 2020, se toma la decisión por parte del gobierno municipal de adecuar sus instalaciones a la nueva normalidad. Como consecuencia de esta situación se pretende, ante todo, garantizar la seguridad tanto de los trabajadores como de los usuarios externos a las instalaciones. Buscamos así soluciones de salubridad que minimicen el impacto del virus en las relaciones y gestiones que se vayan a realizar dentro del ayuntamiento. Para ello tratamos de encontrar las mejores opciones tanto de diseño, como técnicas.','Un ejemplo de ello, es la ventilación forzada para evitar lo máximo posible la estancia del virus en el espacio. Así generamos un falso techo metálico donde ubicamos las instalaciones de ventilación y de climatización.','Por otro lado, procuramos la utilización de materiales de fácil limpieza, sin ornamentación que dificulten su mantenimiento. Estos materiales también van buscando el confort de todos los usuarios, por eso se han utilizado atenuantes acústicos en el techo para minimizar la reverberación. En general, hemos buscado materiales fríos y neutros para dar una imagen tecnológica al proyecto pero a la vez contrarrestando este efecto con la combinación de madera para humanizar ambientes como los puestos de trabajo o las salas de espera y los espacios de reunión.','Mediante el diseño optimizamos circulaciones y estancias donde las distancias de seguridad sean las mayores posibles. Separamos las circulaciones de tránsito de las de estancia creando una nueva entrada y unas cabinas que actúan de filtro para recibir a las personas. Así hay una entrada, con cita previa, en la zona de padrón y registro y otra entrada de tránsito hacia las oficinas municipales situadas en las plantas superiores del edificio.','En las zonas de atención al público, buscamos que los visitantes se den la espalda para evitar riesgos de contagio. Para los trabajadores hemos creado espacios de trabajo o boxes donde están completamente cerrados y protegidos por mamparas mientras se encuentran sentados pero facilitando que se pueden comunicar entre ellos y con los ciudadanos que acudan a realizar sus gestiones.','En cuanto al concepto, la idea base es crear una serie de cajas que contengan funciones. Por un lado, los boxes de trabajo y por otro, las garitas. El techo a diferentes niveles, soportado por grandes pilares de hormigón, también asemejan a su vez a cajas abiertas. El propio espacio es, en definitiva, un juego de cajas que dialogan entre sí y que se yuxtaponen de manera que crean diferentes ambientes que nos ayudan a generar circulaciones y espacios de separación. Estos habitáculos o la generación de estos, se ven favorecidos por el volumen del continente.']::text[],true,11,'mosaico','{"ficha": true, "texto": true, "galeria": true, "planos": true, "siguiente": true}'::jsonb,'[{"id": "ayuntamiento-pontevedra-0", "repo": "ayuntamiento-pontevedra/01.jpg"}, {"id": "ayuntamiento-pontevedra-1", "repo": "ayuntamiento-pontevedra/02.jpg"}, {"id": "ayuntamiento-pontevedra-2", "repo": "ayuntamiento-pontevedra/03.jpg"}, {"id": "ayuntamiento-pontevedra-3", "repo": "ayuntamiento-pontevedra/04.jpg"}, {"id": "ayuntamiento-pontevedra-4", "repo": "ayuntamiento-pontevedra/05.jpg"}, {"id": "ayuntamiento-pontevedra-5", "repo": "ayuntamiento-pontevedra/06.jpg"}, {"id": "ayuntamiento-pontevedra-6", "repo": "ayuntamiento-pontevedra/07.jpg"}]'::jsonb,null),
('pazo-da-buzaca','Pazo da Buzaca','Espacio para eventos en Pazo da Buzaca','Comercio','Moraña, Pontevedra',2022,4000.0,array['La actuación está concentrada en el Pazo existente y los espacios en torno al mismo. Todo el conjunto comprende la edificación de un Pazo, jardines, espacios exteriores de acceso, piscina y pabellón de eventos.','La principal función a la que está destinada el complejo es a la celebración de eventos, especialmente bodas. Para ello, hubo que adecuar todo el espacio exterior y el pabellón a una estética más contemporánea que acompañase la imagen de marca del promotor y facilitase la conexión entre los distintos espacios.','El hilo conductor de toda la actuación es la topografía del entorno, esto se transmite en planos inclinados que se introducen en la fachada y la accesibilidad mediante escaleras y rampas en el espacio exterior.','La fachada del pabellón es cubierta por una membrana de aluminio microperforado que le aporta un importante volumen de planos inclinados y al mismo tiempo no limita la visibilidad ni la luz de dentro a fuera y viceversa. La luz natural, especialmente sobre la fachada, y el paisajismo también tienen relevancia dentro del proyecto.','Dentro del pabellón dos volúmenes dorados configuran espacios de transición y al mismo tiempo ordenan el resto de la superficie, aportando una lectura sencilla del mismo. En el interior de la zona de eventos se opta por un pavimento continúo evitando juntas y trasmitiendo elegancia en contraste con las mesas de los comensales gracias al aspecto homogéneo y neutro que aporta.','La iluminación es tratada con especial detalle. Un cielo de guirnaldas es el componente principal que aporta un aire festivo a este interior. Esta luz base que aportan las guirnaldas se refuerza con proyectores que destacan las mesas de los comensales. Una iluminación indirecta en el perímetro genera una luz ambiente que completa el espacio.']::text[],true,12,'galeria','{"ficha": true, "texto": true, "galeria": true, "planos": true, "siguiente": true}'::jsonb,'[{"id": "pazo-da-buzaca-0", "repo": "pazo-da-buzaca/01.jpg"}, {"id": "pazo-da-buzaca-1", "repo": "pazo-da-buzaca/02.jpg"}, {"id": "pazo-da-buzaca-2", "repo": "pazo-da-buzaca/03.jpg"}, {"id": "pazo-da-buzaca-3", "repo": "pazo-da-buzaca/04.jpg"}, {"id": "pazo-da-buzaca-4", "repo": "pazo-da-buzaca/05.jpg"}, {"id": "pazo-da-buzaca-5", "repo": "pazo-da-buzaca/06.jpg"}, {"id": "pazo-da-buzaca-6", "repo": "pazo-da-buzaca/07.jpg"}]'::jsonb,null),
('clinica-ame','Clínica AME','Clínica dental AME','Clínica','Rosalía de Castro 27, Vigo',2024,120.0,array['La clínica Ame de Vigo donde los grises y los azules se mezclan con curvas y partes rectilíneas para dotar de una gran personalidad a este espacio.','Una sala de espera configurada por varias circunferencias da paso a un bloque de madera que acoge varias estancias con diferentes funciones para el desarrollo de la clínica.','El local tiene una configuración longitudinal, por lo que se van distribuyendo las funciones como una sucesión ordenada.','Primero tenemos la sala de espera con la recepción donde se recibe al paciente y se asesora al cliente, si es necesario se accede al despacho privado inmediatamente detrás de la recepción.','Tras la recepción hemos introducido una gran “L” donde se ubican despacho, gabinetes de trabajo y esterilización. Esta “L” está revestida de un material diferente, en este caso madera de roble en su aspecto natural para aportar calidez al conjunto, dentro de esta nos encontramos un color de pavimento diferenciador del espacio, no de material, porque se busca la continuidad de todo el suelo, pero si diferenciar los espacios a través de los colores.','Enfrentada a esta pieza de madera nos encontramos con espacios de espera, almacenaje y cuarto de baño que complementan la clínica en cuestión de funciones. Esta parte está revestida de un paneleado de madera gris que ilumina de una manera indirecta al pasillo de acceso a la clínica.']::text[],true,13,'mosaico','{"ficha": true, "texto": true, "galeria": true, "planos": true, "siguiente": true}'::jsonb,'[{"id": "clinica-ame-0", "repo": "clinica-ame/01.jpg"}, {"id": "clinica-ame-1", "repo": "clinica-ame/02.jpg"}, {"id": "clinica-ame-2", "repo": "clinica-ame/03.jpg"}, {"id": "clinica-ame-3", "repo": "clinica-ame/04.jpg"}, {"id": "clinica-ame-4", "repo": "clinica-ame/05.jpg"}, {"id": "clinica-ame-5", "repo": "clinica-ame/06.jpg"}, {"id": "clinica-ame-6", "repo": "clinica-ame/07.jpg"}]'::jsonb,null),
('comervia','comervia','Comervia','Comercio','Poio, Pontevedra',2024,650.0,'{}'::text[],true,14,'mosaico','{"ficha": true, "texto": true, "galeria": true, "planos": true, "siguiente": true}'::jsonb,'[{"id": "comervia-0", "repo": "comervia/01.jpg"}, {"id": "comervia-1", "repo": "comervia/02.jpg"}, {"id": "comervia-2", "repo": "comervia/03.jpg"}, {"id": "comervia-3", "repo": "comervia/04.jpg"}, {"id": "comervia-4", "repo": "comervia/05.jpg"}, {"id": "comervia-5", "repo": "comervia/06.jpg"}, {"id": "comervia-6", "repo": "comervia/07.jpg"}]'::jsonb,null),
('pumper-bakery','Pumper Bakery','Pumper Bakery','Comercio','Sagasta 22, Pontevedra',2023,120.0,array['El local a actuar era ya un espacio en funcionamiento y con mucho éxito, el objeto de la intervención era ampliar y actualizar el local.','Nuestros clientes querían ampliar el espacio y aportar una imagen homogénea al mismo.','Se pretendía realizar una intervención contenida conservando mucho de lo pre – existente, pero realizando una transformación sustancial.','La solución fue superficial, aportando color y textura en todos los paramentos. Esto unido a un cambio de iluminación y de mobiliario hizo que el cambio fuera muy importante.','La filosofía de la empresa es la de ser muy sostenible, preocupada con el medio ambiente y con un producto saludable. Por lo tanto, la imagen que se quería transmitir debía ir en consonancia con estos valores. Intentamos de esta manera que los usuarios de la marca tuviesen la sensación de estar en un sitio singular y comprometido.','Para ello se optó por introducir “masas” de color que recorriesen todos los planos, aportando texturas diferentes en variados acabados. Por ejemplo, en la cara exterior de la barra se introdujo un ranurado que lo convierte en un elemento diferenciador.']::text[],true,15,'mosaico','{"ficha": true, "texto": true, "galeria": true, "planos": true, "siguiente": true}'::jsonb,'[{"id": "pumper-bakery-0", "repo": "pumper-bakery/01.jpg"}, {"id": "pumper-bakery-1", "repo": "pumper-bakery/02.jpg"}, {"id": "pumper-bakery-2", "repo": "pumper-bakery/03.jpg"}, {"id": "pumper-bakery-3", "repo": "pumper-bakery/04.jpg"}, {"id": "pumper-bakery-4", "repo": "pumper-bakery/05.jpg"}, {"id": "pumper-bakery-5", "repo": "pumper-bakery/06.jpg"}, {"id": "pumper-bakery-6", "repo": "pumper-bakery/07.jpg"}]'::jsonb,null),
('calefon-headquarters','Calefón Headquarters','Calefón Headquarters','Oficina','Santiago de Compostela',2023,2200.0,'{}'::text[],true,16,'mosaico','{"ficha": true, "texto": true, "galeria": true, "planos": true, "siguiente": true}'::jsonb,'[{"id": "calefon-headquarters-0", "repo": "calefon-headquarters/01.jpg"}, {"id": "calefon-headquarters-1", "repo": "calefon-headquarters/02.jpg"}, {"id": "calefon-headquarters-2", "repo": "calefon-headquarters/03.jpg"}, {"id": "calefon-headquarters-3", "repo": "calefon-headquarters/04.jpg"}, {"id": "calefon-headquarters-4", "repo": "calefon-headquarters/05.jpg"}, {"id": "calefon-headquarters-5", "repo": "calefon-headquarters/06.jpg"}, {"id": "calefon-headquarters-6", "repo": "calefon-headquarters/07.jpg"}]'::jsonb,null),
('finca-sativa','Finca Sativa','Finca Sativa','Vivienda','Aguete, Marín, Pontevedra',2021,140.0,'{}'::text[],true,17,'mosaico','{"ficha": true, "texto": true, "galeria": true, "planos": true, "siguiente": true}'::jsonb,'[{"id": "finca-sativa-0", "repo": "finca-sativa/01.jpg"}, {"id": "finca-sativa-1", "repo": "finca-sativa/02.jpg"}, {"id": "finca-sativa-2", "repo": "finca-sativa/03.jpg"}, {"id": "finca-sativa-3", "repo": "finca-sativa/04.jpg"}, {"id": "finca-sativa-4", "repo": "finca-sativa/05.jpg"}, {"id": "finca-sativa-5", "repo": "finca-sativa/06.jpg"}, {"id": "finca-sativa-6", "repo": "finca-sativa/07.jpg"}]'::jsonb,null),
('flow-estudio-de-yoga-y-movimiento','FLOW estudio de yoga y movimiento','Flow – yoga y movimiento','Clínica','Eduardo Pondal 18, Pontevedra',2020,146.0,array['Dicen que el yoga es la unión del cuerpo y la mente. Nuestro trabajo era buscar un lugar donde esto fuera posible. Crear un espacio cómodo y flexible para practicar deporte a la vez que un ambiente cálido y de calma para la meditación.','El espacio inicial era un lienzo en blanco, una planta larga y estrecha que decidimos dividir en tres secciones según el programa de necesidades. El elemento organizador es un módulo situado en la parte central del local formado por tabiques de ladrillo visto que dibujan un recorrido quebrado en planta y dan fluidez al espacio de circulación. Es aquí donde se alberga la parte del programa destinada a servicios: los aseos, los vestuarios y el almacenaje. A su vez, este elemento delimita los dos espacios principales, uno utilizado como tetería y recepción en el frente del local y otro destinado a la práctica de yoga en el fondo, consiguiendo una continuidad espacial donde cada área se conecta a la anterior y a su vez a la siguiente de manera natural. Para conseguir el ambiente buscado utilizamos una serie de materiales y técnicas constructivas que dan calidez y sencillez al espacio. Por ello decidimos usar los materiales en su estado más natural. La madera, el hormigón con sus imperfecciones y el ladrillo combinados con las instalaciones a la vista y las griferías sin terminar. Así, la esencia del lugar se encuentra en la propia naturaleza y la paz que eso transmite.','Buscamos con el diseño reflejar la filosofía del yoga por lo que el mobiliario juega un papel fundamental. Por ejemplo, la barra continua del espacio de tetería crea un entorno de relación y confianza, y las estanterías hechas a medida para guardar el material en el aula transmiten orden y limpieza. También la conexión directa con el sol es primordial en la práctica del yoga por lo que utilizamos esa simbología en la forma e iluminación de los espejos situados en las zonas más representativas del local.','Igual de importante es la iluminación en el proyecto. Se intenta potenciar la entrada de luz natural en las zonas en contacto con el exterior con grandes ventanales y se complementa con una iluminación artificial estudiada adecuada para cada uno de los diferentes ambientes.','En definitiva, el proyecto simboliza un recorrido donde, al entrar, el usuario deja atrás el acelerado ritmo de vida y va conectando poco a poco con el espacio a través del cuerpo y la mente.']::text[],true,18,'mosaico','{"ficha": true, "texto": true, "galeria": true, "planos": true, "siguiente": true}'::jsonb,'[{"id": "flow-estudio-de-yoga-y-movimiento-0", "repo": "flow-estudio-de-yoga-y-movimiento/01.jpg"}, {"id": "flow-estudio-de-yoga-y-movimiento-1", "repo": "flow-estudio-de-yoga-y-movimiento/02.jpg"}, {"id": "flow-estudio-de-yoga-y-movimiento-2", "repo": "flow-estudio-de-yoga-y-movimiento/03.jpg"}, {"id": "flow-estudio-de-yoga-y-movimiento-3", "repo": "flow-estudio-de-yoga-y-movimiento/04.jpg"}, {"id": "flow-estudio-de-yoga-y-movimiento-4", "repo": "flow-estudio-de-yoga-y-movimiento/05.jpg"}, {"id": "flow-estudio-de-yoga-y-movimiento-5", "repo": "flow-estudio-de-yoga-y-movimiento/06.jpg"}, {"id": "flow-estudio-de-yoga-y-movimiento-6", "repo": "flow-estudio-de-yoga-y-movimiento/07.jpg"}]'::jsonb,null),
('tourmalet-culture-cycliste','Tourmalet Culture Cycliste','Tourmalet Culture Cycliste','Comercio','Rúa do progreso, Sanxenxo (Pontevedra-Galicia / España).',2022,48.0,array['El objeto del proyecto es crear un espacio destinado a la venta de bicicletas y accesorios.','El concepto principal en el que nos basamos para la creación del espacio es el de un velódromo que ayude a marcar las circulaciones, se apoyen todas las funciones de la tienda y se distribuya el material a exponer.','Un gran mueble como elemento central que alberga el mostrador y espacio de exposición es el elemento principal del proyecto reforzado por un hueco en el falso techo en el que se muestra el forjado desnudo haciendo el negativo del mostrador. También se introduce una luminaria suspendida que acompaña en su forma al mobiliario y en el suelo se dibujan unas líneas de colores que simulan las calles por donde circulan los ciclistas.','El mostrador organiza todo el espacio de la tienda, funciona como eje vertebrador de todas las funciones. Realizado en un material metálico, como guiño al material predominante en la realización de las bicicletas.','Al ser un espacio pequeño todo está medido con gran precisión para optimizar de la mejor manera el espacio, por lo tanto, se han diseñado a medida espacios para bicicletas, calzado, calcetines, accesorios, ….','Es buscada la homogeneidad dentro de todo el espacio de tal manera que el producto a exponer gane protagonismo. Para ello, acompañando a las tonalidades metálicas naturales, los paños restantes se pintan de gris. Al igual que el suelo, que se busca un pavimento continuo con acabado en hormigón gris.']::text[],true,19,'mosaico','{"ficha": true, "texto": true, "galeria": true, "planos": true, "siguiente": true}'::jsonb,'[{"id": "tourmalet-culture-cycliste-0", "repo": "tourmalet-culture-cycliste/01.jpg"}, {"id": "tourmalet-culture-cycliste-1", "repo": "tourmalet-culture-cycliste/02.jpg"}, {"id": "tourmalet-culture-cycliste-2", "repo": "tourmalet-culture-cycliste/03.jpg"}, {"id": "tourmalet-culture-cycliste-3", "repo": "tourmalet-culture-cycliste/04.jpg"}, {"id": "tourmalet-culture-cycliste-4", "repo": "tourmalet-culture-cycliste/05.jpg"}, {"id": "tourmalet-culture-cycliste-5", "repo": "tourmalet-culture-cycliste/06.jpg"}, {"id": "tourmalet-culture-cycliste-6", "repo": "tourmalet-culture-cycliste/07.jpg"}]'::jsonb,null),
('vivienda-herreros','Vivienda Herreros','Vivienda particular','Vivienda','Rúa dos ferreiros, Pontevedra',2022,120.0,array['Un apartamento para una persona soltera y sus dos hijos.','Nuestro cliente adquiere una vivienda antigua en el centro de Pontevedra y consciente de su potencial pretende una reforma integral del mismo.','El promotor tiene una sensibilidad especial, ya que es una persona vinculada al mundo del arte y con una gran afición por la literatura. El diseño y la arquitectura por lo tanto son materias en las que se desenvuelve con seguridad.','Para su vivienda las premisas a seguir es que sea un espacio singular y sobrio, así como atemporal para que la reforma sea lo más duradera posible en el tiempo y envejezca bien.','Espacialmente la planta es bastante sencilla, se busca una zona de entrada donde integrar el espacio de salón/cocina y a continuación, mediante un pequeño pasillo, llegar a la zona de noche donde se ubican dormitorios, lavandería y cuartos de baño.','Después de la distribución en planta se opta por diseñar e integrar casi por completo el mobiliario, así se generan muebles en salón, se diseña la cocina y las habitaciones son actuaciones donde no se adquiere ningún mueble, simplemente se diseña el espacio acompañado de su mobiliario a medida. Igualmente ocurre en los cuartos de baño, donde un material cerámico de gran formato hace que todos los paramentos sean iguales, eliminando también plato de ducha, consiguiendo así una imagen muy fuerte y consistente.']::text[],true,20,'mosaico','{"ficha": true, "texto": true, "galeria": true, "planos": true, "siguiente": true}'::jsonb,'[{"id": "vivienda-herreros-0", "repo": "vivienda-herreros/01.jpg"}, {"id": "vivienda-herreros-1", "repo": "vivienda-herreros/02.jpg"}, {"id": "vivienda-herreros-2", "repo": "vivienda-herreros/03.jpg"}, {"id": "vivienda-herreros-3", "repo": "vivienda-herreros/04.jpg"}, {"id": "vivienda-herreros-4", "repo": "vivienda-herreros/05.jpg"}, {"id": "vivienda-herreros-5", "repo": "vivienda-herreros/06.jpg"}, {"id": "vivienda-herreros-6", "repo": "vivienda-herreros/07.jpg"}]'::jsonb,null),
('clinica-adriana-diaz','Clínica Adriana Díaz','Clínica Dental Adriana Díaz García','Clínica','Calle Frai Juan Navarrete,3,1º (Pontevedra-Galicia / España).',2015,62.0,array['El principal problema en este proyecto era encajar un programa muy extenso en una superficie muy reducida, apenas 62 m2. Tenía 3 zonas diferenciadas por sus usos: una primera de recepción con cuartos de baño, una segunda con instalaciones, depósito, diagnóstico y despacho, y una tercera con 2 gabinetes.','Nuestra propuesta fue la de dividir estos 3 espacios con un sencillo gesto. 2 piezas en forma de trapecio que se separan o se unen y que contienen la zona de instalaciones y jerarquizan todo el resto del espacio.','Lo que se busca con este sutil gesto es crear un espacio diáfano con pocas divisiones, de manera que se produzca una fácil comprensión de todas sus funciones.','La parte principal del proyecto es donde se encuentran los gabinetes, por este motivo están situados en la zona de ventanas hacia el exterior, hacia la calle.','Los materiales empleados juegan un papel muy importante a nivel compositivo, se han escogido dependiendo de las zonas o funciones. Estos son en su mayoría aluminio y madera de pino.','La pieza central principal está realizada en aluminio, este material está buscado con la idea de trasmitir una sensación de limpieza y asepsia que debe de tener una clínica dental. Un gran volumen metálico que se contrae o dilata de manera a formar las diferentes estancias de la clínica.']::text[],true,21,'mosaico','{"ficha": true, "texto": true, "galeria": true, "planos": true, "siguiente": true}'::jsonb,'[{"id": "clinica-adriana-diaz-0", "repo": "clinica-adriana-diaz/01.jpg"}, {"id": "clinica-adriana-diaz-1", "repo": "clinica-adriana-diaz/02.jpg"}, {"id": "clinica-adriana-diaz-2", "repo": "clinica-adriana-diaz/03.jpg"}, {"id": "clinica-adriana-diaz-3", "repo": "clinica-adriana-diaz/04.jpg"}, {"id": "clinica-adriana-diaz-4", "repo": "clinica-adriana-diaz/05.jpg"}, {"id": "clinica-adria